&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;What&amp;nbsp;You’ll&amp;nbsp;Be Launching&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;We&#39;re&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;&amp;nbsp;looking for a UX Researcher who thrives in complex problem spaces and cares deeply about creating seamless, effective, and meaningful experiences for users in high-stakes environments. In this role,&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;you’ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;&amp;nbsp;be a key advocate for the voice of the user—championing research-driven design decisions across multiple product teams.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:false,&amp;quot;134245529&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
